pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 newVal) internal {
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(newVal) {} catch { return; }
        assertTrue(c.MinSum() == newVal);
    }

    function testFuzz_run(uint256 newVal) public {
        _run(newVal);
    }

    receive() external payable {}

    fallback() external payable {}
}
